WITH exploded AS (SELECT id, service, log_ts, level, status_code, key, value FROM app_logs LATERAL VIEW EXPLODE(context) e AS key, value), base AS (SELECT *, DATE_TRUNC('MONTH', log_ts) AS log_ts_period, COALESCE(key, 'NONE') AS key_filled FROM exploded WHERE log_ts >= TIMESTAMP '2025-06-01 14:00:00' AND key IS NOT NULL AND level NOT IN ('ERROR', 'INFO')), with_gaps AS (SELECT *, CASE WHEN log_ts - LAG(log_ts) OVER (PARTITION BY key ORDER BY log_ts, id, key) > INTERVAL 15 MINUTES THEN 1 ELSE 0 END AS session_start_flag FROM base), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY key ORDER BY log_ts, id, key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps), ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY key ORDER BY log_ts, id, key) AS row_num FROM sessionized QUALIFY row_num = 1), kept_keys AS (SELECT service, id FROM ranked INTERSECT SELECT service, id FROM app_logs WHERE log_ts < '2024-01-01'), verified AS (SELECT s.* FROM ranked s INNER JOIN kept_keys k ON s.service = k.service AND s.id = k.id), enriched AS (SELECT *, DENSE_RANK() OVER (PARTITION BY key ORDER BY session_no DESC) AS session_no_dense_rank, RANK() OVER (PARTITION BY service, level ORDER BY session_no) AS session_no_rank, AVG(session_no) OVER (PARTITION BY key ORDER BY CAST(log_ts_period AS BIGINT) RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW) AS session_no_avg_7d FROM verified) SELECT id, level, status_code, key, log_ts_period, key_filled, session_no, row_num, session_no_dense_rank FROM enriched ORDER BY key DESC NULLS LAST
